  "output": "package com.gymie.shared.ui.components

import com.gymie.shared.api.ApiException
import kotlin.coroutines.cancellation.CancellationException

/**
 * Failure copy more than one screen falls back to when a request fails and the throwable itself
 * carries no message, kept in one place so the wording cannot drift between the call sites.
 */
object FailureMessages {
    /**
     * Shared by [com.gymie.shared.ui.SettingsState.load] and the workout editor's own read of the
     * same `GET /preferences` endpoint (predicting a brand-new workout's unit before it is created).
     */
    const val COULD_NOT_LOAD_WEIGHT_UNIT = "Could not load your weight unit."

    /**
     * Shared by [com.gymie.shared.ui.workout.ActiveWorkoutState.bootstrap] and the workout editor's
     * own catalog fetch (`WorkoutEditorScreen`'s `LaunchedEffect`) — both load the whole exercise
     * catalog before anything else and report it identically when that fails.
     */
    const val COULD_NOT_LOAD_EXERCISE_CATALOG = "Could not load the exercise catalog."

    /**
     * Shared by [com.gymie.shared.ui.workout.ActiveWorkoutState.load] and the workout editor's own
     * `GET /workouts/{id}` (`WorkoutEditorScreen`'s `LaunchedEffect`) — both fetch the workout itself
     * and report it identically when that fails.
     */
    const val COULD_NOT_LOAD_WORKOUT = "Could not load the workout."

    /**
     * Shared by [com.gymie.shared.ui.profile.ProfileState.load] and the edit form's own read of the
     * same `GET /api/profile/me` — both fetch the owner's whole profile and report it identically
     * when that fails.
     */
    const val COULD_NOT_LOAD_PROFILE = "Could not load your profile."
}

/**
 * Runs [action] for every failure this [Result] holds *except* [CancellationException], which is
 * rethrown instead of reaching [action], and a `403 grant_revoked` [ApiException], which is
 * dropped instead of reaching [action].
 *
 * Any `runCatching { <suspend network call> }.onFailure { ... }` block that reports through
 * [NotificationState.failure] needs exactly this: the caller navigating away mid-request cancels the
 * coroutine, which surfaces here as a `CancellationException` thrown through the very `runCatching`
 * meant to catch *domain* failures. Treating that as one more failure to report would raise a
 * spurious "Could not …" notification for a request nobody is waiting on any more, and swallowing it
 * would also stop the cancellation from propagating — leaving the coroutine cancelled in name only.
 *
 * The rethrow happens before [action] runs, and is the only thing [onFailureNotCancelled] does
 * before delegating to it — that ordering is what keeps it from being buried under a call site's own
 * logic the way a hand-written `if` at the top of an inline `onFailure` block can be.
 *
 * ### The `grant_revoked` drop (KAN-345 fix round 4, F14)
 *
 * `ApiRequestSupport.reportGrantRevokedAndThrow` already handles a `403 grant_revoked`
 * [ApiException] in full before it ever reaches a caller: `SwitchState.onGrantRevoked` has dropped
 * home and reported the designed "<name> took back your access." notice through
 * [NotificationState.failure], then the support layer rethrows so the caller's own cancellation and
 * cleanup logic still runs — `design.md`'s `revoked-detected-in-one-place` decision. But
 * [NotificationState] holds only one notice at a time, and every call site downstream still catches
 * that rethrow through this same helper and reports the backend's own `ProblemDetail` text — the
 * designed notice was shown and immediately overwritten in the same frame, so the user only ever saw
 * the backend string. A `grant_revoked` [ApiException] has nothing left for a caller to say: it is
 * the one code this helper drops here, once, rather than leaving every current and future call site
 * to special-case it. This is deliberately narrower than the [CancellationException] rethrow above —
 * it does not generalize to swallowing errors, only to this one code the central hook has already
 * fully handled.
 *
 * ### The invariant, not an enumeration
 *
 * An earlier revision of this doc named every call site and asserted the list was exhaustive,
 * checked by `grep -rn "\.onFailure {" shared/src/commonMain`. KAN-341 added several more call
 * sites (`FriendsState`, `FindPeopleState`, `PersonProfileState`, `OpenOwnProfileLink`) on top of
 * the ones KAN-340 and earlier changes already added, which is what made that list stale enough to
 * replace rather than extend again: a list a reader must keep re-verifying against the source is
 * strictly worse than the invariant it stands in for. The invariant is simple enough to state once
 * and hold without re-listing: **every `runCatching { <suspend network call> }` in `commonMain`
 * that reports a failure — to [NotificationState], to a screen's own error slot, or by logging —
===
    // alone (KAN-517 § 10); defaulted so the several desktopTests composing this screen directly are
    // left untouched.
    preferences: BooleanPreferences = remember { LocalPreferencesStore() },
) {
    BroadsheetTheme {
        val scope = rememberCoroutineScope()
        val settings = remember(api, notifications) { SettingsState(api, notifications) }
        LaunchedEffect(settings) { settings.load() }
        val profile = rememberProfileOrNull(api)
        val bodyUnits = remember(api, notifications) { BodyUnitState(api, notifications) }
        LaunchedEffect(profile) { profile?.let(bodyUnits::adopt) }
        Column(
            modifier =
                Modifier
                    .fillMaxSize()
                    .padding(BroadsheetTheme.space.space6)
                    .testTag("screen_settings"),
            // Frame A4's own 15dp internal gap between these rows, kept as they were. The 20dp
            // rhythm the outer Column used to apply between *groups* went with the groups.
            verticalArrangement = Arrangement.spacedBy(BroadsheetTheme.space.space3),
        ) {
            if (settings.hasLoaded) {
                DisplayUnitSetting(settings = settings, scope = scope)
                // The 1px neutral-300 rule frame A4 draws between the two rows. It sits *between* the
                // two settings rather than inside either, so it leaves `DisplayUnitSetting` and
                // `BodyUnitsSetting` themselves untouched.
                HorizontalDivider(
                    thickness = 1.dp,
                    color = BroadsheetTheme.colors.neutral300,
                    modifier = Modifier.testTag("settings_app_divider"),
                )
                // A shimmer row until the profile answers: the control is neither drawn greyed nor
                // selected on a default, then flipped (KAN-575 fix round 12).
                if (profile != null) {
                    BodyUnitsSetting(bodyUnits = bodyUnits, profile = profile, scope = scope)
                } else {
                    BroadsheetSkeleton(
                        width = 350.dp,
                        height = MIN_TOUCH_TARGET,
                        kind = BroadsheetSkeletonKind.Shimmer,
                        modifier = Modifier.testTag(BODY_UNITS_SKELETON_TAG),
                    )
                }
                HorizontalDivider(
                    thickness = 1.dp,
                    color = BroadsheetTheme.colors.neutral300,
                    modifier = Modifier.testTag("settings_session_view_divider"),
                )
                WorkoutModeSetting(settings = settings, scope = scope)
                // KAN-517 § 10 — draws nothing outside its own allow-list; see its own doc.
                ShowFrameRateSetting(profile = profile, preferences = preferences)
            } else {
                ScreenSkeleton()
            }
        }
    }
}

/**
 * Signs this device out, wherever the control that asked lives.
 *
 * KAN-189 task 10.3: the server scopes sign-out to whichever session presents its own refresh token
 * (task 10.2), so the client sends the one this device holds. **Clearing the local session is
 * unconditional** — a server that refuses the call (offline, already-consumed token) must not leave
 * the user stuck signed in.
 *
 * Its own function since KAN-573 task 3: the drawer's foot carries `Log out` now (`design.md` §4)
 * beside Settings' own button, and a second copy of this sequence is the one that would forget the
 * unconditional clear.
 */
internal suspend fun signOut(
    api: GymieApiClient,
    session: SessionStore,
    onLoggedOut: () -> Unit,
) {
    val refreshToken = session.refreshToken()
    runCatching { if (refreshToken != null) api.logout(RefreshRequest(refreshToken)) }
    session.clear()
    clearViewerHolders()
    onLoggedOut()
}

/** This screen's own focus-visible ring width — the same 2dp [WorkoutEditorScreen.kt]'s segmented-control chrome uses. */
private val SETTINGS_FOCUS_RING_WIDTH = 2.dp

/**
 * Chooses the unit **newly created** workouts are stamped with.
 *
 * It changes nothing about a workout that already exists: no stored weight is converted and no open
 * screen is invalidated, which is why nothing here bumps the shell's content refresh.
 */
@Composable
private fun DisplayUnitSetting(
    settings: SettingsState,
    scope: CoroutineScope,
) {
    val colors = BroadsheetTheme.colors
    Column(verticalArrangement = Arrangement.spacedBy(BroadsheetTheme.space.space1)) {
        // KAN-339 task 7: label and control now share one line — a Row rather than the stacked
        // Column this used to be. Everything below the row (state, progress line, disabled logic)
        // is unchanged.
        Row(verticalAlignment = Alignment.CenterVertically, modifier = Modifier.fillMaxWidth()) {
            Column {
                Text("Weight unit", style = BroadsheetTheme.type.body, color = colors.text)
                Text("For sets in workouts", style = BroadsheetTheme.type.caption, color = colors.neutral700)
            }
            Spacer(modifier = Modifier.weight(1f))
            BroadsheetInlineSegmentedControl(
                options = WeightUnit.entries,
                selected = settings.displayUnit,
                label = WorkoutLabels::weightUnit,
                enabled = true,
                testTag = "settings_display_unit",
                optionTag = { "settings_display_unit_${it.name}" },
                onSelect = { option -> scope.launch { settings.chooseUnit(option) } },
            )
        }
        // **There is no progress line here, deliberately.** A `Working…` caption used to sit
        // between the control and the retry affordance. It is gone at the operator's explicit
        // instruction: a write to this screen is a single segmented-control tap that the control
        // itself already reflects — it disables while the write is in flight — so the caption
        // announced something the user could already see, and announced it on every tap.
